import re

def entities(doc, scope):
    scope_node = node_by_title(doc, scope)
    if scope_node is None:
        return []
    objects_node = None
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child and child.get('kind') == 'list' and 'Objects' in child['title']:
            objects_node = child
            break
    if objects_node is None:
        return []
    result = []
    for line in objects_node.get('lines', []):
        match = re.match(r'Object (\d+): (.+)', line)
        if match:
            result.append({"id": match.group(1), "description": match.group(2)})
    return result

def recorded_end(doc, scope):
    scope_node = node_by_title(doc, scope)
    if scope_node is None:
        return None
    max_frame = None
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child is None:
            continue
        if child.get('kind') == 'list' and 'Events' in child['title']:
            for line in child.get('lines', []):
                m = re.match(r'Frame (\d+):', line)
                if m:
                    f = int(m.group(1))
                    if max_frame is None or f > max_frame:
                        max_frame = f
        elif child.get('kind') == 'table' and 'Motion log' in child['title']:
            for row_idx, row_data in table_rows(child):
                fs = row_data.get('frame', '')
                if fs:
                    try:
                        f = int(fs)
                        if max_frame is None or f > max_frame:
                            max_frame = f
                    except ValueError:
                        pass
    return float(max_frame) if max_frame is not None else None

def inputs(doc, scope):
    scope_node = node_by_title(doc, scope)
    if scope_node is None:
        return []

    objects_node = None
    events_node = None
    motion_log_node = None

    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child is None:
            continue
        if child.get('kind') == 'list' and 'Objects' in child['title']:
            objects_node = child
        elif child.get('kind') == 'list' and 'Events' in child['title']:
            events_node = child
        elif child.get('kind') == 'table' and 'Motion log' in child['title']:
            motion_log_node = child

    if events_node is None:
        return []

    obj_line_map = {}
    if objects_node:
        for idx, line in enumerate(objects_node.get('lines', [])):
            m = re.match(r'Object (\d+):', line)
            if m:
                obj_line_map[m.group(1)] = idx

    motion_lookup = {}
    if motion_log_node:
        for row_idx, row_data in table_rows(motion_log_node):
            fs = row_data.get('frame', '')
            os = row_data.get('object', '')
            if fs and os:
                try:
                    frame = int(fs)
                    om = re.match(r'(\d+)', os)
                    if om:
                        motion_lookup[(frame, om.group(1))] = (row_idx, row_data)
                except ValueError:
                    pass

    inputs_list = []
    for line_idx, line in enumerate(events_node.get('lines', [])):
        m_input = re.match(
            r'Frame (\d+): Object (\d+) \(.+?\) (?:is in view when the video begins|enters the scene)\.', 
            line)
        if m_input:
            frame = int(m_input.group(1))
            obj_id = m_input.group(2)
            kind = "object_present" if "is in view" in line else "object_enter"

            fields = {}
            src = [[events_node['node_id'], line_idx]]

            if obj_id in obj_line_map and objects_node:
                src.append([objects_node['node_id'], obj_line_map[obj_id]])

            key = (frame, obj_id)
            if key in motion_lookup:
                r_idx, r_data = motion_lookup[key]
                fields = {
                    'x': float(r_data.get('x', '0')),
                    'y': float(r_data.get('y', '0')),
                    'vx': float(r_data.get('vx', '0')),
                    'vy': float(r_data.get('vy', '0')),
                    'speed': float(r_data.get('speed', '0'))
                }
                src.append([motion_log_node['node_id'], r_idx, ['frame', 'object', 'x', 'y', 'vx', 'vy', 'speed']])

            inputs_list.append({
                "id": f"{kind}_{frame}_{obj_id}",
                "time": float(frame),
                "kind": kind,
                "entities": [obj_id],
                "fields": fields,
                "src": src
            })

    return inputs_list

def outcomes(doc, scope):
    scope_node = node_by_title(doc, scope)
    if scope_node is None:
        return []

    events_node = None
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child and child.get('kind') == 'list' and 'Events' in child['title']:
            events_node = child
            break

    if events_node is None:
        return []

    outcomes_list = []
    for line_idx, line in enumerate(events_node.get('lines', [])):
        m_col = re.match(
            r'Frame (\d+): Object (\d+) \(.+?\) collides with Object (\d+) \(.+?\)\.', line)
        if m_col:
            outcomes_list.append({
                "time": float(int(m_col.group(1))),
                "kind": "collision",
                "entities": [m_col.group(2), m_col.group(3)],
                "value": None,
                "src": [[events_node['node_id'], line_idx]]
            })
            continue

        m_exit = re.match(
            r'Frame (\d+): Object (\d+) \(.+?\) exits the scene\.', line)
        if m_exit:
            outcomes_list.append({
                "time": float(int(m_exit.group(1))),
                "kind": "exit",
                "entities": [m_exit.group(2)],
                "value": None,
                "src": [[events_node['node_id'], line_idx]]
            })
            continue

    return outcomes_list

def params(doc, scope):
    return {"stationary_threshold": 0.1}


# ---- step 2: forward model ----
import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = 127.0
    if start is None:
        start = 0.0

    dt = 0.0278
    friction = 0.993
    coll_thresh = 0.48
    stationary_threshold = params.get('stationary_threshold', 0.1)
    x_min, x_max = -8.0, 8.0
    y_min, y_max = -3.0, 3.0

    sorted_inputs = sorted(inputs, key=lambda i: i['time'])
    obj_entries = {}
    for inp in sorted_inputs:
        for eid in inp['entities']:
            obj_entries[eid] = {
                'time': inp['time'],
                'x': inp['fields']['x'],
                'y': inp['fields']['y'],
                'vx': inp['fields']['vx'],
                'vy': inp['fields']['vy']
            }

    if not obj_entries:
        return []

    # Get motion log for better initialization
    scope_node = node_by_title(doc, scope)
    motion_lookup = {}
    if scope_node:
        motion_log_node = None
        for child_id in scope_node.get('children', []):
            child = node_by_id(doc, child_id)
            if child and child.get('kind') == 'table' and 'Motion log' in child['title']:
                motion_log_node = child
                break
        if motion_log_node:
            for row_idx, row_data in table_rows(motion_log_node):
                fs = row_data.get('frame', '').strip()
                os = row_data.get('object', '').strip()
                xs = row_data.get('x', '').strip()
                ys = row_data.get('y', '').strip()
                vxs = row_data.get('vx', '').strip()
                vys = row_data.get('vy', '').strip()
                if fs and os and xs and ys and vxs and vys:
                    try:
                        frame = int(fs)
                        obj_match = re.match(r'(\d+)', os)
                        if obj_match:
                            oid = obj_match.group(1)
                            motion_lookup[(frame, oid)] = {
                                'x': float(xs), 'y': float(ys),
                                'vx': float(vxs), 'vy': float(vys)
                            }
                    except (ValueError, TypeError):
                        pass

    def interp_state(oid, frame):
        best = None
        for (f, o), data in motion_lookup.items():
            if o == oid and f <= frame:
                if best is None or f > best[0]:
                    best = (f, data)
        if best:
            f0, s0 = best
            s = {'x': s0['x'], 'y': s0['y'], 'vx': s0['vx'], 'vy': s0['vy']}
            for fi in range(f0, frame):
                speed = math.sqrt(s['vx']**2 + s['vy']**2)
                if speed > stationary_threshold:
                    s['vx'] *= friction
                    s['vy'] *= friction
                    s['x'] += s['vx'] * dt
                    s['y'] += s['vy'] * dt
                    if math.sqrt(s['vx']**2 + s['vy']**2) < stationary_threshold:
                        s['vx'] = 0.0
                        s['vy'] = 0.0
            return s
        return None

    start_frame = int(start)
    end_frame = int(math.ceil(horizon))

    # Initialize state at start_frame
    state = {}
    for oid, entry in obj_entries.items():
        s = interp_state(oid, start_frame)
        if s is None:
            entry_frame = int(entry['time'])
            s = {'x': entry['x'], 'y': entry['y'], 'vx': entry['vx'], 'vy': entry['vy']}
            for fi in range(entry_frame, start_frame):
                speed = math.sqrt(s['vx']**2 + s['vy']**2)
                if speed > stationary_threshold:
                    s['vx'] *= friction
                    s['vy'] *= friction
                    s['x'] += s['vx'] * dt
                    s['y'] += s['vy'] * dt
                    if math.sqrt(s['vx']**2 + s['vy']**2) < stationary_threshold:
                        s['vx'] = 0.0
                        s['vy'] = 0.0
        state[oid] = s

    outcomes = []
    collided_pairs = set()

    for frame in range(start_frame, end_frame + 1):
        active = list(state.keys())

        for oid in active:
            s = state[oid]
            speed = math.sqrt(s['vx']**2 + s['vy']**2)
            if speed > stationary_threshold:
                s['vx'] *= friction
                s['vy'] *= friction
                s['x'] += s['vx'] * dt
                s['y'] += s['vy'] * dt
                if math.sqrt(s['vx']**2 + s['vy']**2) < stationary_threshold:
                    s['vx'] = 0.0
                    s['vy'] = 0.0

        to_remove = []
        for oid in active:
            s = state[oid]
            if s['x'] < x_min or s['x'] > x_max or s['y'] < y_min or s['y'] > y_max:
                to_remove.append(oid)
        for oid in to_remove:
            outcomes.append({'time': float(frame), 'kind': 'exit',
                            'entities': [oid], 'value': None, 'src': []})
            del state[oid]
            active.remove(oid)

        new_collisions = []
        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                o1, o2 = active[i], active[j]
                pair = tuple(sorted([o1, o2]))
                if pair in collided_pairs:
                    continue
                s1, s2 = state[o1], state[o2]
                dx = s2['x'] - s1['x']
                dy = s2['y'] - s1['y']
                dist = math.sqrt(dx**2 + dy**2)
                if dist < coll_thresh:
                    new_collisions.append((o1, o2, pair, dx, dy, dist))

        for o1, o2, pair, dx, dy, dist in new_collisions:
            collided_pairs.add(pair)
            s1, s2 = state[o1], state[o2]
            if dist > 1e-6:
                nx, ny = dx / dist, dy / dist
                dvx = s1['vx'] - s2['vx']
                dvy = s1['vy'] - s2['vy']
                dot = dvx * nx + dvy * ny
                s1['vx'] -= dot * nx
                s1['vy'] -= dot * ny
                s2['vx'] += dot * nx
                s2['vy'] += dot * ny
                overlap = max(0, coll_thresh - dist)
                s1['x'] -= nx * overlap * 0.5
                s1['y'] -= ny * overlap * 0.5
                s2['x'] += nx * overlap * 0.5
                s2['y'] += ny * overlap * 0.5
            outcomes.append({'time': float(frame), 'kind': 'collision',
                            'entities': [o1, o2], 'value': None, 'src': []})

    return outcomes

