import re

def entities(doc, scope):
    scope_node = node_by_title(doc, scope)
    if scope_node is None:
        return []
    objects_node = None
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child and child.get('kind') == 'list' and 'Objects' in child['title']:
            objects_node = child
            break
    if objects_node is None:
        return []
    result = []
    for line in objects_node.get('lines', []):
        match = re.match(r'Object (\d+): (.+)', line)
        if match:
            result.append({"id": match.group(1), "description": match.group(2)})
    return result

def recorded_end(doc, scope):
    scope_node = node_by_title(doc, scope)
    if scope_node is None:
        return None
    max_frame = None
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child is None:
            continue
        if child.get('kind') == 'list' and 'Events' in child['title']:
            for line in child.get('lines', []):
                m = re.match(r'Frame (\d+):', line)
                if m:
                    f = int(m.group(1))
                    if max_frame is None or f > max_frame:
                        max_frame = f
        elif child.get('kind') == 'table' and 'Motion log' in child['title']:
            for row_idx, row_data in table_rows(child):
                fs = row_data.get('frame', '')
                if fs:
                    try:
                        f = int(fs)
                        if max_frame is None or f > max_frame:
                            max_frame = f
                    except ValueError:
                        pass
    return float(max_frame) if max_frame is not None else None

def inputs(doc, scope):
    scope_node = node_by_title(doc, scope)
    if scope_node is None:
        return []

    objects_node = None
    events_node = None
    motion_log_node = None

    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child is None:
            continue
        if child.get('kind') == 'list' and 'Objects' in child['title']:
            objects_node = child
        elif child.get('kind') == 'list' and 'Events' in child['title']:
            events_node = child
        elif child.get('kind') == 'table' and 'Motion log' in child['title']:
            motion_log_node = child

    if events_node is None:
        return []

    obj_line_map = {}
    if objects_node:
        for idx, line in enumerate(objects_node.get('lines', [])):
            m = re.match(r'Object (\d+):', line)
            if m:
                obj_line_map[m.group(1)] = idx

    motion_lookup = {}
    if motion_log_node:
        for row_idx, row_data in table_rows(motion_log_node):
            fs = row_data.get('frame', '')
            os = row_data.get('object', '')
            if fs and os:
                try:
                    frame = int(fs)
                    om = re.match(r'(\d+)', os)
                    if om:
                        motion_lookup[(frame, om.group(1))] = (row_idx, row_data)
                except ValueError:
                    pass

    inputs_list = []
    for line_idx, line in enumerate(events_node.get('lines', [])):
        m_input = re.match(
            r'Frame (\d+): Object (\d+) \(.+?\) (?:is in view when the video begins|enters the scene)\.', 
            line)
        if m_input:
            frame = int(m_input.group(1))
            obj_id = m_input.group(2)
            kind = "object_present" if "is in view" in line else "object_enter"

            fields = {}
            src = [[events_node['node_id'], line_idx]]

            if obj_id in obj_line_map and objects_node:
                src.append([objects_node['node_id'], obj_line_map[obj_id]])

            key = (frame, obj_id)
            if key in motion_lookup:
                r_idx, r_data = motion_lookup[key]
                fields = {
                    'x': float(r_data.get('x', '0')),
                    'y': float(r_data.get('y', '0')),
                    'vx': float(r_data.get('vx', '0')),
                    'vy': float(r_data.get('vy', '0')),
                    'speed': float(r_data.get('speed', '0'))
                }
                src.append([motion_log_node['node_id'], r_idx, ['frame', 'object', 'x', 'y', 'vx', 'vy', 'speed']])

            inputs_list.append({
                "id": f"{kind}_{frame}_{obj_id}",
                "time": float(frame),
                "kind": kind,
                "entities": [obj_id],
                "fields": fields,
                "src": src
            })

    return inputs_list

def outcomes(doc, scope):
