    outcomes_list = []
    for line_idx, line in enumerate(events_node.get('lines', [])):
        m_col = re.match(
            r'Frame (\d+): Object (\d+) \(.+?\) collides with Object (\d+) \(.+?\)\.', line)
        if m_col:
            outcomes_list.append({
                "time": float(int(m_col.group(1))),
                "kind": "collision",
                "entities": [m_col.group(2), m_col.group(3)],
                "value": None,
                "src": [[events_node['node_id'], line_idx]]
            })
            continue

        m_exit = re.match(
