# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = 200.0
    if start is None:
        start = 0.0

    # Determine earliest time to simulate from to properly initialize state
    min_t = int(start)
    for inp in inputs:
        if inp['time'] < min_t:
            min_t = int(inp['time'])

    # Estimated physics parameters from recorded data
    friction = 0.995        # velocity multiplier per frame
    x_lim, y_lim = 8.0, 4.0 # scene bounds (exit triggers when exceeded)
    coll_thresh = 0.45      # distance threshold for collision detection

    state = {}
    outcomes = []
    collided_pairs = set()

    sorted_inputs = sorted(inputs, key=lambda i: i['time'])
    inp_idx = 0

    for frame in range(min_t, int(horizon) + 1):
        # Inject new objects from inputs as they enter/present
        while inp_idx < len(sorted_inputs) and sorted_inputs[inp_idx]['time'] <= frame:
            inp = sorted_inputs[inp_idx]
            oid = inp['entities'][0]
            state[oid] = {
                'x': inp['fields']['x'],
                'y': inp['fields']['y'],
                'vx': inp['fields']['vx'],
                'vy': inp['fields']['vy']
            }
            inp_idx += 1

        active = list(state.keys())

        # Apply friction and update positions
        for oid in active:
            s = state[oid]
            s['vx'] *= friction
            s['vy'] *= friction
            s['x'] += s['vx']
            s['y'] += s['vy']

        # Detect exits
        exited = []
        for oid in active:
            s = state[oid]
            if abs(s['x']) > x_lim or abs(s['y']) > y_lim:
                exited.append(oid)

        for oid in exited:
            if frame >= start:
                outcomes.append({'time': float(frame), 'kind': 'exit', 'entities': [oid], 'value': None, 'src': []})
            del state[oid]
            active.remove(oid)

        # Detect collisions
        new_collisions = []
        for i in range(len(active)):
            for j in range(i+1, len(active)):
                o1, o2 = active[i], active[j]
                pair = tuple(sorted([o1, o2]))
                if pair in collided_pairs:
                    continue
                s1, s2 = state[o1], state[o2]
                dx = s2['x'] - s1['x']
                dy = s2['y'] - s1['y']
                dist = (dx**2 + dy**2)**0.5
                if dist < coll_thresh:
                    new_collisions.append((o1, o2))
                    collided_pairs.add(pair)

        # Resolve collisions (equal mass, 2D elastic approximation)
        for o1, o2 in new_collisions:
            s1, s2 = state[o1], state[o2]
            dx = s2['x'] - s1['x']
            dy = s2['y'] - s1['y']
            dist_sq = dx**2 + dy**2
            if dist_sq < 1e-6: dist_sq = 1e-6

            dvx = s1['vx'] - s2['vx']
            dvy = s1['vy'] - s2['vy']
            dot = (dvx * dx + dvy * dy) / dist_sq

            s1['vx'] -= dot * dx
            s1['vy'] -= dot * dy
            s2['vx'] += dot * dx
            s2['vy'] += dot * dy

            if frame >= start:
                outcomes.append({'time': float(frame), 'kind': 'collision', 'entities': [o1, o2], 'value': None, 'src': []})

    return outcomes

