import math

def analyze_video(scope):
    scope_node = node_by_title(doc, scope)
    motion_log_node = None
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child and child.get('kind') == 'table' and 'Motion log' in child['title']:
            motion_log_node = child
            break

    if motion_log_node is None:
        return {}

    obj_data = {}
    for row_idx, row_data in table_rows(motion_log_node):
        frame = int(row_data['frame'])
        obj_match = re.match(r'(\d+)', row_data['object'])
        obj_id = obj_match.group(1)
        if obj_id not in obj_data:
            obj_data[obj_id] = []
        obj_data[obj_id].append({
            'frame': frame,
            'x': float(row_data['x']),
            'y': float(row_data['y']),
            'vx': float(row_data['vx']),
            'vy': float(row_data['vy']),
            'speed': float(row_data['speed'])
        })

    # Estimate dt from position changes
    dt_estimates = []
    friction_estimates = []

    for obj_id, records in obj_data.items():
        records.sort(key=lambda r: r['frame'])
        for i in range(len(records) - 1):
            r1 = records[i]
            r2 = records[i + 1]
            df = r2['frame'] - r1['frame']
            if df > 0 and r1['speed'] > 0.1:
                avg_vx = (r1['vx'] + r2['vx']) / 2
                avg_vy = (r1['vy'] + r2['vy']) / 2
                dx = r2['x'] - r1['x']
                dy = r2['y'] - r1['y']

                if abs(avg_vx) > 0.01:
                    dt_x = dx / (avg_vx * df)
                    dt_estimates.append(dt_x)
                if abs(avg_vy) > 0.01:
                    dt_y = dy / (avg_vy * df)
                    dt_estimates.append(dt_y)

                if r1['speed'] > 0.1:
                    friction = r2['speed'] / r1['speed'] ** (1/df)
                    if friction > 0 and friction < 1.1:
                        friction_estimates.append(friction)

    return {'dt': dt_estimates, 'friction': friction_estimates}

