import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = 127.0
    if start is None:
        start = 0.0

    # Physics parameters calibrated from data
    dt = 0.0278
    friction = 0.993
    coll_thresh = 0.5
    stationary_threshold = params.get('stationary_threshold', 0.1)

    # Exit bounds (calibrated from exit events)
    x_min, x_max = -7.0, 7.0
    y_min, y_max = -3.02, 2.7

    # Get motion log data
    scope_node = node_by_title(doc, scope)
    motion_log_node = None
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child and child.get('kind') == 'table' and 'Motion log' in child['title']:
            motion_log_node = child
            break

    # Build per-object motion history
    obj_motion = {}
    if motion_log_node:
        for row_idx, row_data in table_rows(motion_log_node):
            frame = int(row_data['frame'])
            obj_match = re.match(r'(\d+)', row_data['object'])
            obj_id = obj_match.group(1)
            if obj_id not in obj_motion:
                obj_motion[obj_id] = []
            obj_motion[obj_id].append({
                'frame': frame,
                'x': float(row_data['x']),
                'y': float(row_data['y']),
                'vx': float(row_data['vx']),
                'vy': float(row_data['vy'])
            })
        for obj_id in obj_motion:
            obj_motion[obj_id].sort(key=lambda r: r['frame'])

    # Get all object IDs from inputs
    all_obj_ids = set()
    for inp in inputs:
        for eid in inp['entities']:
            all_obj_ids.add(eid)

    sorted_inputs = sorted(inputs, key=lambda i: i['time'])

    # Helper: apply one frame of physics
    def step(s):
        speed = math.sqrt(s['vx']**2 + s['vy']**2)
        if speed > stationary_threshold:
            s['vx'] *= friction
            s['vy'] *= friction
            s['x'] += s['vx'] * dt
            s['y'] += s['vy'] * dt
            new_speed = math.sqrt(s['vx']**2 + s['vy']**2)
            if new_speed < stationary_threshold:
                s['vx'] = 0.0
                s['vy'] = 0.0

    # Initialize state at start
    state = {}
    start_frame = int(start)

    for oid in all_obj_ids:
        best = None
        if oid in obj_motion:
            for rec in obj_motion[oid]:
                if rec['frame'] <= start_frame:
                    if best is None or rec['frame'] > best['frame']:
                        best = rec

        if best:
            state[oid] = {'x': best['x'], 'y': best['y'],
                          'vx': best['vx'], 'vy': best['vy']}
            for f in range(best['frame'], start_frame):
                step(state[oid])
        else:
            for inp in sorted_inputs:
                if inp['entities'][0] == oid and inp['time'] <= start_frame:
                    state[oid] = {'x': inp['fields']['x'], 'y': inp['fields']['y'],
                                  'vx': inp['fields']['vx'], 'vy': inp['fields']['vy']}
                    entry_frame = int(inp['time'])
                    for f in range(entry_frame, start_frame):
                        step(state[oid])

    # Simulate forward
    end_frame = int(math.ceil(horizon))
    outcomes = []
    collided_pairs = set()

    for frame in range(start_frame, end_frame + 1):
        # Add new objects from inputs
        for inp in sorted_inputs:
            if inp['kind'] == 'object_enter' and int(inp['time']) == frame:
                oid = inp['entities'][0]
                state[oid] = {'x': inp['fields']['x'], 'y': inp['fields']['y'],
                              'vx': inp['fields']['vx'], 'vy': inp['fields']['vy']}

        active = list(state.keys())

        # Apply friction and update positions
        for oid in active:
            step(state[oid])

        # Check for exits
        to_remove = []
        for oid in active:
            s = state[oid]
            if s['x'] < x_min or s['x'] > x_max or s['y'] < y_min or s['y'] > y_max:
                to_remove.append(oid)
        for oid in to_remove:
            outcomes.append({'time': float(frame), 'kind': 'exit',
                            'entities': [oid], 'value': None, 'src': []})
            del state[oid]
            active.remove(oid)

        # Check for collisions
        new_collisions = []
        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                o1, o2 = active[i], active[j]
                pair = tuple(sorted([o1, o2]))
                if pair in collided_pairs:
                    continue
                s1, s2 = state[o1], state[o2]
                dx = s2['x'] - s1['x']
                dy = s2['y'] - s1['y']
                dist = math.sqrt(dx**2 + dy**2)
                if dist < coll_thresh:
                    new_collisions.append((o1, o2, pair, dx, dy, dist))

        # Resolve collisions
        for o1, o2, pair, dx, dy, dist in new_collisions:
            collided_pairs.add(pair)
            s1, s2 = state[o1], state[o2]

            # Elastic collision (equal mass)
            if dist > 1e-6:
                nx, ny = dx / dist, dy / dist
                dvx = s1['vx'] - s2['vx']
                dvy = s1['vy'] - s2['vy']
                dot = dvx * nx + dvy * ny
                s1['vx'] -= dot * nx
                s1['vy'] -= dot * ny
                s2['vx'] += dot * nx
                s2['vy'] += dot * ny

            # Separate objects to avoid re-collision
            sep = max(0, coll_thresh / 2 - dist) + 0.02
            if dist > 1e-6:
                s1['x'] -= (dx / dist) * sep
                s1['y'] -= (dy / dist) * sep
                s2['x'] += (dx / dist) * sep
                s2['y'] += (dy / dist) * sep

            outcomes.append({'time': float(frame), 'kind': 'collision',
                            'entities': [o1, o2], 'value': None, 'src': []})

    return outcomes

